Rules.InvariantScript:
Set(
    vSavedEmergency,
    Patch(
        Incidents_2,
        LookUp(Incidents_2, ID = vSavedEmergency.ID),
        {
            Statues: {Value: "On the way"}
        }
    )
);

Set(vActionStatus, "On the way");

Notify("Status updated: On the way", NotificationType.Success)

Set(
    vSavedEmergency,
    Patch(
        Incidents_2,
        LookUp(Incidents_2, ID = vSavedEmergency.ID),
        {
            Statues: {Value: "Arrived"}
        }
    )
);

Set(vActionStatus, "Arrived");

Notify("Status updated: Arrived", NotificationType.Success)

Set(
    vSavedEmergency,
    Patch(
        Incidents_2,
        LookUp(Incidents_2, ID = vSavedEmergency.ID),
        {
            Statues: {Value: "Cancelled"}
        }
    )
);

Notify("Emergency cancelled", NotificationType.Warning);

Navigate(VolunteerScreen, ScreenTransition.Fade)

Set(
    vSavedEmergency,
    Patch(
        Incidents_2,
        LookUp(Incidents_2, ID = vSavedEmergency.ID),
        {
            Statues: {Value: "Completed"}
        }
    )
);

Set(vActionStatus, "Completed");

Notify("Emergency completed", NotificationType.Success);

Navigate(ResolvedScreen, ScreenTransition.Fade)

Set(
    vSavedEmergency,
    Patch(
        Incidents_2,
        LookUp(Incidents_2, ID = vSavedEmergency.ID),
        {
            Statues: {Value: "Completed"}
        }
    )
);

Set(vActionStatus, "Completed");

Notify("Emergency completed", NotificationType.Success);

Navigate(ResolvedScreen, ScreenTransition.Fade)

If(
    IsBlank(txtResponderMessage.Text),
    Notify("Please type a message first.", NotificationType.Error),

    Set(
        vSavedEmergency,
        Patch(
            Incidents_2,
            LookUp(Incidents_2, ID = vSavedEmergency.ID),
            {
                ResponderMessage:
                    Coalesce(
                        LookUp(Incidents_2, ID = vSavedEmergency.ID).ResponderMessage,
                        ""
                    ) &
                    If(
                        IsBlank(LookUp(Incidents_2, ID = vSavedEmergency.ID).ResponderMessage),
                        "",
                        Char(10) & Char(10)
                    ) &
                    Text(Now(), "hh:mm AM/PM") &
                    " - Responder: " &
                    txtResponderMessage.Text
            }
        )
    );

    Notify("Message saved to SharePoint", NotificationType.Success);
    Reset(txtResponderMessage)
)
